import pathlib,json
root=pathlib.Path('/home/appontrack/public_html/mobile/updates')
d={}
for key,p in [('native',root/'native/latest.json'),('ui',root/'latest.json')]:
 try:
  envelope=json.loads(p.read_text())
  meta=json.loads(envelope['payload'])
  d[key]={k:meta.get(k) for k in ('version_code','version_name','revision','sha256','source_commit','channel')}
 except Exception as e:d[key]={'error':type(e).__name__}
print(json.dumps(d))
